"use client";
import Link from "next/link";import { useEffect,useState } from "react";import AdminShell,{Card,PageHeader} from "../../../components/admin/admin-shell";import { Plus, Search, Pencil, Trash2, ExternalLink } from "lucide-react";
export default function Vendors(){const [data,setData]=useState<any>({items:[],pages:1});const [q,setQ]=useState("");const [category,setCategory]=useState("");const [status,setStatus]=useState("");const [page,setPage]=useState(1);const [loading,setLoading]=useState(true);async function load(){setLoading(true);const p=new URLSearchParams({q,category,status,page:String(page)});const r=await fetch(`/api/admin/vendors?${p}`);if(r.ok)setData(await r.json());setLoading(false)}useEffect(()=>{load()},[q,category,status,page]);async function del(id:string){if(!confirm("Are you sure you want to delete this vendor?"))return;const r=await fetch(`/api/admin/vendors/${id}`,{method:"DELETE"});if(r.ok)load();}return <AdminShell><PageHeader title="Vendors" description="Manage every wedding professional in the marketplace." action={<Link href="/admin/vendors/new" className="inline-flex items-center gap-2 rounded-xl bg-[#c8a45d] px-4 py-3 text-sm font-semibold text-white"><Plus size={17}/>Add vendor</Link>}/><Card className="overflow-hidden"><div className="flex flex-col gap-3 border-b p-4 md:flex-row"><div className="relative flex-1"><Search size={17} className="absolute left-3 top-3.5 text-black/35"/><input value={q} onChange={e=>{setPage(1);setQ(e.target.value)}} placeholder="Search vendors…" className="w-full rounded-xl border px-10 py-3 text-sm outline-none"/></div><select value={category} onChange={e=>{setPage(1);setCategory(e.target.value)}} className="rounded-xl border px-4 py-3 text-sm"><option value="">All categories</option>{["Photographer","Makeup Artist","Decorator","Caterer","Mehendi Artist","DJ"].map(x=><option key={x}>{x}</option>)}</select><select value={status} onChange={e=>{setPage(1);setStatus(e.target.value)}} className="rounded-xl border px-4 py-3 text-sm"><option value="">All status</option><option value="active">Active</option><option value="inactive">Inactive</option></select></div><div className="overflow-x-auto"><table className="w-full min-w-[850px] text-left text-sm"><thead className="bg-black/[.025] text-xs uppercase tracking-wider text-black/45"><tr><th className="p-4">Vendor</th><th>Category</th><th>City</th><th>Price</th><th>Rating</th><th>Status</th><th className="p-4">Actions</th></tr></thead><tbody className="divide-y">{loading?<tr><td colSpan={7} className="p-10 text-center text-black/40">Loading vendors…</td></tr>:data.items.map((v:any)=><tr key={v._id}><td className="p-4"><div className="flex items-center gap-3"><img src={v.profileImage} className="h-10 w-10 rounded-xl object-cover"/><div><p className="font-medium">{v.name}</p><p className="text-xs text-black/40">{new Date(v.createdAt).toLocaleDateString()}</p></div></div></td><td>{v.category}</td><td>{v.city}</td><td>₹{v.startingPrice.toLocaleString("en-IN")}{v.pricingUnit==="per_plate"?" / plate":""}</td><td>★ {v.rating.toFixed(1)}</td><td><span className={`rounded-full px-3 py-1 text-xs ${v.status==="active"?"bg-green-50 text-green-700":"bg-black/5 text-black/50"}`}>{v.status}</span></td><td className="p-4"><div className="flex items-center gap-2"><Link title="View" href={`/vendors/${v.slug}`} target="_blank" className="rounded-lg border p-2"><ExternalLink size={15}/></Link><Link title="Edit" href={`/admin/vendors/${v._id}/edit`} className="rounded-lg border p-2"><Pencil size={15}/></Link><button title="Delete" onClick={()=>del(v._id)} className="rounded-lg border p-2 text-red-600"><Trash2 size={15}/></button></div></td></tr>)}{!loading&&!data.items.length&&<tr><td colSpan={7} className="p-10 text-center text-black/40">No vendors found.</td></tr>}</tbody></table></div><div className="flex items-center justify-between border-t p-4 text-sm"><span className="text-black/45">Page {data.page||page} of {data.pages||1}</span><div className="flex gap-2"><button disabled={page<=1} onClick={()=>setPage(p=>p-1)} className="rounded-lg border px-3 py-2 disabled:opacity-30">Previous</button><button disabled={page>=(data.pages||1)} onClick={()=>setPage(p=>p+1)} className="rounded-lg border px-3 py-2 disabled:opacity-30">Next</button></div></div></Card></AdminShell>}
